#!/usr/bin/env node
'use strict';
const fs = require('node:fs'), path = require('node:path'), cp = require('node:child_process'), crypto = require('node:crypto');
const review = 'progress-clarity-20261128';
const patchHash = '59dede6a9671381a694d2ee801b485815875f4e2a1d55e273435535892ff014a';
const patch = Buffer.from('', 'base64').toString('utf8');
const files = ['app/(tabs)/tracking/index.tsx', 'app/progress/connections.tsx',
  'components/progress/JourneyDashboard.tsx', 'components/progress/ProgressDashboard.tsx',
  'components/progress/ProgressSummary.tsx', 'docs/progress-clarity.md',
  'hooks/useProgressHealth.ts', 'lib/progress-summary.ts', 'package.json',
  'tests/progress-clarity.cjs', 'tests/unified-progress.cjs'];
function git(args, input) { return cp.spawnSync('git', args, { cwd: process.cwd(), encoding: 'utf8', input, maxBuffer: 16 * 1024 * 1024 }); }
function fail(message) { console.error(message); process.exit(1); }
const root = git(['rev-parse', '--show-toplevel']);
if (root.status !== 0) fail('Abrí Git Bash dentro de TreksorDevCompleto.');
process.chdir(root.stdout.trim());
const remote = git(['remote', 'get-url', 'origin']);
if (remote.status !== 0 || !/treksorapp-cmd\/TreksorApp(?:\.git)?\s*$/i.test(remote.stdout)) fail('El repositorio no es TreksorApp. No se modificó nada.');
if (git(['ls-files', '-u']).stdout.trim()) fail('Hay un conflicto de Git pendiente. No se modificó nada.');
if (crypto.createHash('sha256').update(patch).digest('hex') !== patchHash) fail('El instalador y el parche son de versiones distintas. No se modificó nada.');
for (const file of files) {
  let current = process.cwd();
  for (const part of file.split('/')) {
    current = path.join(current, part);
    if (fs.existsSync(current) && fs.lstatSync(current).isSymbolicLink()) fail('No se puede modificar un enlace: ' + file);
  }
}
if (git(['apply', '--reverse', '--check', '--whitespace=nowarn', '-'], patch).status === 0) {
  console.log('PROGRESS CLARO YA INSTALADO. Reiniciá Expo y abrí Treksor Dev.');
  process.exit(0);
}
const check = git(['apply', '--check', '--whitespace=nowarn', '-'], patch);
if (check.status !== 0) {
  console.error(check.stderr);
  fail('Tu copia tiene cambios que se superponen. No se modificó ningún archivo. Conservá esta salida para adaptar el parche.');
}
if (!process.argv.includes('--apply')) {
  console.log('COMPATIBLE: ' + files.length + ' archivos comprobados. No se escribió nada. Usá --apply para instalar con respaldo.');
  process.exit(0);
}
const compiler = path.join(process.cwd(), 'node_modules/typescript/bin/tsc');
if (!fs.existsSync(compiler)) fail('Faltan las dependencias de esta copia de Treksor. No se modificó nada.');
const original = new Map(files.map(file => [file, fs.existsSync(file) ? fs.readFileSync(file) : null]));
const backup = fs.mkdtempSync(path.join(path.dirname(process.cwd()), 'Treksor-progress-clarity-backup-'));
for (const [file, bytes] of original) {
  if (bytes !== null) { const target = path.join(backup, file); fs.mkdirSync(path.dirname(target), { recursive: true }); fs.writeFileSync(target, bytes); }
}
fs.writeFileSync(path.join(backup, 'manifest.json'), JSON.stringify({ root: process.cwd(), review, files: files.map(file => ({ file, existed: original.get(file) !== null })) }, null, 2));
const applied = git(['apply', '--whitespace=nowarn', '-'], patch);
function restore() {
  for (const [file, bytes] of original) {
    if (bytes === null) fs.rmSync(file, { force: true });
    else fs.writeFileSync(file, bytes);
  }
}
if (applied.status !== 0) { restore(); fail('No se pudo aplicar. Se restauraron los archivos. Respaldo: ' + backup); }
for (const args of [[compiler, '--noEmit', '-p', 'tsconfig.mobile.json'], ['tests/progress-clarity.cjs'], ['tests/unified-progress.cjs']]) {
  const result = cp.spawnSync(process.execPath, args, { cwd: process.cwd(), stdio: 'inherit', timeout: 180000 });
  if (result.status !== 0) {
    restore();
    fail('La validación de tu copia local falló. Se restauraron los archivos originales. Respaldo: ' + backup);
  }
}
console.log('PROGRESS CLARO INSTALADO Y VALIDADO. Respaldo: ' + backup);
console.log('Tu rama y tus datos se conservaron. Reiniciá Expo en esta misma carpeta y abrí Treksor Dev.');
console.log('La nueva pantalla dice: Your effort, made clear.');
